const { Window } = require('happy-dom');
const fs = require('fs');

const html = fs.readFileSync('index.html', 'utf-8');
const win = new Window({ url: 'http://localhost' });
const doc = win.document;
doc.documentElement.innerHTML = html.replace(/<!doctype[^>]*>/i, '').replace(/<html[^>]*>/i, '').replace(/<\/html>/i, '');

// Manually implement the app without using eval
let todos = [];
let currentFilter = '/';

function save() {
  try { win.localStorage.setItem('todos-vanillajs', JSON.stringify(todos)); } catch(e) {}
}

function render() {
  const main = doc.querySelector('.main');
  const footer = doc.querySelector('.footer');
  const todoList = doc.querySelector('.todo-list');
  const counter = doc.querySelector('.todo-count strong');
  const toggleAll = doc.querySelector('#toggle-all');
  const clearBtn = doc.querySelector('.clear-completed');

  if (todos.length === 0) {
    main.style.display = 'none';
    footer.style.display = 'none';
    return;
  }

  main.style.display = '';
  footer.style.display = '';

  todoList.innerHTML = '';
  todos.forEach(function(todo) {
    const li = doc.createElement('li');
    li.dataset.id = todo.id;
    if (todo.completed) li.classList.add('completed');

    const divView = doc.createElement('div');
    divView.className = 'view';

    const checkbox = doc.createElement('input');
    checkbox.className = 'toggle';
    checkbox.type = 'checkbox';
    checkbox.checked = todo.completed;

    const label = doc.createElement('label');
    label.textContent = todo.title;

    const destroyBtn = doc.createElement('button');
    destroyBtn.className = 'destroy';

    divView.appendChild(checkbox);
    divView.appendChild(label);
    divView.appendChild(destroyBtn);

    const editInput = doc.createElement('input');
    editInput.className = 'edit';
    editInput.value = todo.title;

    li.appendChild(divView);
    li.appendChild(editInput);
    todoList.appendChild(li);
  });

  const activeCount = todos.filter(function(t) { return !t.completed; }).length;
  counter.textContent = activeCount;
  counter.parentNode.textContent = activeCount + (activeCount === 1 ? ' item left' : ' items left');

  const allCompleted = todos.length > 0 && todos.every(function(t) { return t.completed; });
  toggleAll.checked = allCompleted;

  const hasCompleted = todos.some(function(t) { return t.completed; });
  clearBtn.style.display = hasCompleted ? '' : 'none';
}

function addTodo(title) {
  const trimmed = title.trim();
  if (!trimmed) return;
  todos.push({ id: Date.now().toString(36), title: trimmed, completed: false });
  save();
  render();
}

function updateTodo(id, title) {
  const trimmed = title.trim();
  if (!trimmed) {
    todos = todos.filter(function(t) { return t.id !== id; });
    save();
    render();
    return;
  }
  todos.forEach(function(t) { if (t.id === id) t.title = trimmed; });
  save();
  render();
}

// Setup event listeners
doc.addEventListener('DOMContentLoaded', function() {
  render();

  const newTodoInput = doc.querySelector('.new-todo');
  newTodoInput.addEventListener('keydown', function(e) {
    if (e.keyCode === 13) {
      addTodo(newTodoInput.value);
      newTodoInput.value = '';
    }
  });

  doc.querySelector('.todo-list').addEventListener('dblclick', function(e) {
    console.log('DBLCLICK fired, target:', e.target.tagName, e.target.className);
    if (e.target.tagName !== 'LABEL') return;
    const li = e.target.closest('li');
    if (!li) return;
    console.log('li found:', !!li);
    li.classList.add('editing');
    const editInput = li.querySelector('.edit');
    console.log('editInput:', !!editInput);

    function finishEdit() {
      console.log('finishEdit called');
      updateTodo(li.dataset.id, editInput.value);
      li.classList.remove('editing');
      editInput.removeEventListener('blur', finishEdit);
      editInput.removeEventListener('keydown', handleKey);
    }

    function handleKey(ev) {
      console.log('handleKey called, keyCode:', ev.keyCode);
      if (ev.keyCode === 13) {
        updateTodo(li.dataset.id, editInput.value);
        editInput.removeEventListener('blur', finishEdit);
        editInput.removeEventListener('keydown', handleKey);
      } else if (ev.keyCode === 27) {
        editInput.value = li.querySelector('label').textContent;
        finishEdit();
      }
    }

    editInput.addEventListener('blur', finishEdit);
    editInput.addEventListener('keydown', handleKey);
    console.log('Listeners added');
  });
});

doc.dispatchEvent(new win.Event('DOMContentLoaded'));

